      "children": [
        {
          "type": "mol",
          "smiles": "C/C(=C/[C@H]1O[C@@H](C/C=C/C=O)C[C@H](O)[C@H]1C)CO",
          "children": [
            {
              "type": "reaction",
              "template_id": 74197,
